const retrieval = $input.first()?.json ?? {};
const priority = { project_data: 0, project_computed_result: 1, project_document: 2, project_data_record: 3 };
const contexts = (Array.isArray(retrieval.contexts) ? retrieval.contexts : []).map((item, index) => ({ item, index })).sort((a, b) => {
  const priorityDelta = (priority[String(a.item?.source_type)] ?? 9) - (priority[String(b.item?.source_type)] ?? 9);
  return priorityDelta || a.index - b.index;
}).map(({ item }) => item);
return [{ json: { ...retrieval, contexts } }];

const state = $('Validate Step Request').first().json;
const retrieval = $input.first()?.json ?? {};
const projectData = state.project_data && typeof state.project_data === 'object' ? state.project_data : {};
const projectCitations = (Array.isArray(projectData.citations) ? projectData.citations : []).filter((item) => item && item.citation_id && item.content);
const existingCitations = Array.isArray(retrieval.citations) ? retrieval.citations : [];
const citationMap = new Map();
for (const item of [...projectCitations, ...existingCitations]) citationMap.set(String(item.citation_id), item);
const projectContexts = projectCitations.map((item) => ({
  chunk_key: String(item.citation_id),
  citation_id: String(item.citation_id),
  title: String(item.title ?? item.dataset_id ?? '项目数据'),
  section: String(item.section ?? item.source_locator ?? ''),
  page_start: item.page_start ?? null,
  page_end: item.page_end ?? null,
  source_url: String(item.source_url ?? ''),
  content: String(item.content ?? ''),
  source_type: String(item.source_type ?? 'project_data'),
  dataset_id: String(item.dataset_id ?? ''),
  snapshot_id: String(item.snapshot_id ?? ''),
  complete: item.complete !== false,
}));
const existingContexts = Array.isArray(retrieval.contexts) ? retrieval.contexts : [];
return [{ json: {
  ...retrieval,
  citations: [...citationMap.values()],
  contexts: [...projectContexts, ...existingContexts],
  project_data_status: String(projectData.status ?? 'unavailable'),
  project_data_queries: Array.isArray(projectData.queries) ? projectData.queries : [],
  project_data_warnings: Array.isArray(projectData.warnings) ? projectData.warnings : [],
} }];

const state = $input.first().json;
const output = state.decision_state.steps[state.step_key];
return [{ json: {
  run_id: state.run_id,
  step_key: state.step_key,
  step_order: state.step_order,
  status: 'completed',
  output,
  decision_state: state.decision_state,
} }];

const input = $input.first()?.json ?? {};
for (const field of ['run_id', 'step_key', 'step_title']) {
  if (typeof input[field] !== 'string' || !input[field].trim()) throw new Error('missing required field: ' + field);
}
if (!/^[0-9a-f-]{36}$/i.test(input.run_id)) throw new Error('run_id must be a UUID');
const stepOrder = Number(input.step_order);
if (!Number.isInteger(stepOrder) || stepOrder < 1 || stepOrder > 12) throw new Error('step_order must be between 1 and 12');
const list = (value) => Array.isArray(value) ? value.map(String).filter(Boolean) : [];
const decisionState = input.decision_state && typeof input.decision_state === 'object'
  ? input.decision_state
  : { steps: {}, evidence_index: {} };
const projectQuestion = String(input.project_question ?? input.question ?? '').trim();
return [{ json: {
  ...input,
  step_order: stepOrder,
  tenant_id: String(input.tenant_id ?? 'default'),
  access_groups: list(input.access_groups),
  project_types: list(input.project_types),
  geography: list(input.geography),
  metadata_filter: input.metadata_filter && typeof input.metadata_filter === 'object' ? input.metadata_filter : {},
  decision_state: decisionState,
  project_question: projectQuestion,
  retrieval_query: [projectQuestion, input.step_title].filter(Boolean).join('\n'),
} }];

parameters.query:
INSERT INTO analysis_step_outputs (run_id, step, step_order, status, input_snapshot, quality_gate, updated_at)
VALUES ($1::uuid, $2::text, $3::integer, 'running', $4::jsonb, $5::jsonb, NOW())
ON CONFLICT (run_id, step) DO UPDATE SET
  step_order = EXCLUDED.step_order, status = 'running', input_snapshot = EXCLUDED.input_snapshot,
  quality_gate = EXCLUDED.quality_gate, updated_at = NOW();
UPDATE analysis_runs SET status = 'running', current_step = $2::text, started_at = COALESCE(started_at, NOW()), updated_at = NOW()
WHERE id = $1::uuid;
SELECT $1::text AS run_id;

