const state = $('Validate Step Request').first().json;
return [{ json: {
  query: state.retrieval_query,
  tenant_id: state.tenant_id,
  access_groups: state.access_groups,
  decision_steps: [state.step_key],
  project_types: state.project_types,
  geography: state.geography,
  metadata_filter: state.metadata_filter,
  candidate_limit: 40,
  result_limit: 10,
  context_radius: 1,
} }];

const state = $('Validate Step Request').first().json;
const retrieval = $input.first()?.json ?? {};
const contexts = (Array.isArray(retrieval.contexts) ? retrieval.contexts : []).slice(0, 12).map((item) => ({
  title: String(item.title ?? ''),
  section: String(item.section ?? ''),
  page_start: item.page_start ?? null,
  page_end: item.page_end ?? null,
  source_url: String(item.source_url ?? ''),
  content: String(item.content ?? '').slice(0, 2500),
}));
const previous = Object.entries(state.decision_state.steps ?? {}).map(([, value]) => ({
  title: String(value?.title ?? '前一章节'),
  reader_chapter: String(value?.reader_chapter ?? '').slice(0, 2400),
}));
const schema = {
  type: 'object',
  properties: { reader_chapter: { type: 'string', minLength: 1 } },
  required: ['reader_chapter'],
  additionalProperties: false,
};
const instructions = [
  '为当前分析方向撰写一章可直接发表在项目报告中的中文正文。读者是项目甲方、政府决策者、投资人和非技术评审者。',
  '正文应使用自然标题和普通读者能理解的表达，直接说明判断、依据、候选路径之间的取舍、反证、不确定性、成立条件和待核验事项。内容长度由证据复杂度决定，不套固定短摘要模板。',
  '数据和证据应在相关判断附近自然说明来源类型与适用边界；不得输出引用 ID、内部文件名、字段名、状态枚举、节点名、工作流名、规则名或任何执行过程说明。',
  '不得出现 step_01 一类步骤键、decision_state、quality_gate、evidence_index、n8n、UUID、JSON 字段说明或类似工程术语。不要把条件性判断改写成确定事实。',
  '只返回完整章节正文，不要解释写作过程，不要另附审计数据。',
  '需要补充事实时，自主调用项目数据工具；工具背后通过 MCP 读取项目数据。',
  `当前章节：${state.step_title}。`,
].join('\n');
const userPayload = JSON.stringify({ project_question: state.project_question, chapter_title: state.step_title, previous_chapters: previous, source_context: contexts });
const conversationItems = [{ role: 'user', content: [{ type: 'input_text', text: userPayload }] }];
return [{ json: {
  state,
  retrieval,
  instructions,
  input: conversationItems,
  conversation_items: conversationItems,
  max_output_tokens: 5000,
  reasoning: { effort: 'medium' },
  agent_turn: 0,
  parallel_tool_calls: false,
  tools: [
    { type: 'function', name: 'project_context', description: 'Read current project context and available datasets.', parameters: { type: 'object', properties: {}, additionalProperties: false } },
    { type: 'function', name: 'query_data', description: 'Query one project dataset for facts needed by this direction.', parameters: { type: 'object', properties: { dataset_id: { type: 'string' }, operation: { type: 'string', enum: ['records', 'aggregate'] }, filters: { type: 'object' }, spatial: { type: 'object' }, sort: { type: 'object' }, group_by: { type: 'array', items: { type: 'string' } }, metrics: { type: 'array', items: { type: 'object' } }, continue_token: { type: 'string' } }, required: ['dataset_id'], additionalProperties: false } },
  ],
  text: { format: { type: 'json_schema', name: 'reader_chapter', strict: true, schema } },
} }];

const request = $('Build Structured Decision Request').first().json;
const response = $input.first()?.json ?? {};
let parsed;
try { parsed = JSON.parse(String(response.output_text ?? '')); } catch { throw new Error('reader_chapter_invalid_json'); }
const state = request.state;
const readerChapter = String(parsed.reader_chapter ?? '').trim();
const leakagePatterns = [
  /step[_-]?\d{1,2}/i, /decision_state/i, /quality_gate/i, /evidence_index/i, /\bn8n\b/i,
  /(?:node|节点)[ _-]?(?:id|编号)/i, /(?:run|workflow|response)[ _-]?id/i,
  /\b(?:queued|running|completed|failed|cancelled|revision_required)\b/i,
  /\b[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}\b/i,
  /(?:project|result|document):[a-z0-9._:-]{6,}/i, /\bE\d{3,}\b/i,
  /(?:page|block|chunk)[ _:-]?\d+/i, /\b[a-z][a-z0-9]*(?:_[a-z0-9]+)+\b/i,
  /\b(?:phase\s*\d+|[GDP]\d+)\b/i,
];
if (!readerChapter) throw new Error('reader_chapter_empty');
if (leakagePatterns.some((pattern) => pattern.test(readerChapter))) throw new Error('reader_chapter_contains_internal_terms');
const evidenceSignals = ['项目材料', '项目数据', '空间数据', '公开资料', '现场', '核验', '证据', '数据显示', '材料显示'];
if (!evidenceSignals.some((signal) => readerChapter.includes(signal))) throw new Error('reader_chapter_missing_evidence_context');
const conditionSignals = ['条件', '前提', '尚未', '不能', '需要', '待核验', '不确定', '若', '如果'];
if (!conditionSignals.some((signal) => readerChapter.includes(signal))) throw new Error('reader_chapter_missing_conditions');
const output = { title: state.step_title, reader_chapter: readerChapter };
const nextDecisionState = {
  ...state.decision_state,
  steps: { ...(state.decision_state.steps ?? {}), [state.step_key]: output },
  current_step: state.step_key,
};
return [{ json: { result: {
  run_id: state.run_id, step_key: state.step_key, step_order: state.step_order, status: 'completed',
  output, decision_state: nextDecisionState,
} } }];

