const response = $input.first()?.json ?? {};
const call = Array.isArray(response.tool_calls) ? response.tool_calls[0] : null;
if (!call?.name || !call?.call_id) throw new Error('invalid_agent_tool_call');
return [{ json: { ...response, mcp_tool_name: String(call.name), mcp_arguments: call.arguments && typeof call.arguments === 'object' ? call.arguments : {}, mcp_call_id: String(call.call_id), agent_turn: Number(response.agent_turn ?? 0) + 1 } }];

const prior = $('Prepare MCP Agent Tool Call').item.json;
const toolResult = $input.first()?.json ?? {};
if (Number(prior.agent_turn ?? 0) > 6) throw new Error('agent_tool_turn_limit');
const conversationItems = Array.isArray(prior.conversation_items) ? prior.conversation_items : [];
const responseItems = Array.isArray(prior.output) ? prior.output : [];
const result = toolResult.structured_content ?? toolResult.content ?? toolResult;
const normalizedToolResult = {
  tool_name: String(toolResult.tool_name ?? prior.mcp_tool_name ?? ''),
  is_error: toolResult.is_error === true,
  result,
};
const nextItems = [
  ...conversationItems,
  ...responseItems,
  { type: 'function_call_output', call_id: prior.mcp_call_id, output: JSON.stringify(normalizedToolResult) },
];
return [{ json: { ...prior, input: nextItems, conversation_items: nextItems, output: [] } }];
